import * as echarts from "echarts";
import {upLeft, zx, arm, x86, czxt, zzt, downRight} from "@/api/assets/itaiDevice";
import {mapGetters} from "vuex";

export default {
  name: "testPage",
  data() {
    return {
      pageLoading: false,
      screenInfo: {},
      selectBtnType: 'CORP',

      zdbbLoading: false,

      upLeftLoading: false,
      zxLoading: false,
      zztLoading: false,
      downRightLoading: false,
    };
  },
  computed: {
    ...mapGetters(["userDetail"]),
  },
  watch: {
    'screenInfo.deviceAll'(newVal, oldVal) {
      if (!isNaN(newVal)) {
        if (!isNaN(this.screenInfo.deviceNum)) {
          //加载initChart3
          this.initChart3();
        }
      }
    },
    'screenInfo.deviceNum'(newVal, oldVal) {
      if (!isNaN(this.screenInfo.deviceAll)) {
        //加载initChart3
        this.initChart3();
      }
    },
  },
  mounted() {
    this.requestScreenInfo();
  },
  methods: {
    requestScreenInfo() {
      //先初始化，防止切换页面eChart图形错乱
      this.initChart1();
      this.initChart2();
      this.initChart3();

      let uInfo = this.userDetail;
      let pms = {area: uInfo.regionCode, userId: uInfo.userId, ownerUnitCode: uInfo.ownerUnit};

      this.upLeftLoading = true;
      upLeft(pms).then(res => {
        for (const resKey in res.data) {
          this.screenInfo[resKey] = res.data[resKey];
        }
      }).finally(() => {
        this.upLeftLoading = false;
        if (!isNaN(this.screenInfo.deviceNum)) {
          if (!isNaN(this.screenInfo.deviceAll)) {
            //加载initChart3
            this.initChart3();

            this.downRightLoading = false;
            this.upLeftLoading = false;
          }
        }
      })

      this.downRightLoading = true;
      downRight(pms).then(res => {
        for (const resKey in res.data) {
          this.screenInfo[resKey] = res.data[resKey];
        }
      }).finally(() => {
        if (!isNaN(this.screenInfo.deviceAll)) {
          if (!isNaN(this.screenInfo.deviceNum)) {
            //加载initChart3
            this.initChart3();

            this.downRightLoading = false;
            this.upLeftLoading = false;
          }
        }
      })


      this.zxLoading = true;
      zx(pms).then(res => {
        if (res.data && res.data.sevenDay) {
          this.screenInfo.sevenDay = res.data.sevenDay;
          this.initChart1();
        }
      }).finally(() => {
        this.zxLoading = false;
      });
      this.zztLoading = true;
      zzt(pms).then(res => {
        if (res.data && res.data.dept) {
          this.screenInfo.dept = res.data.dept;
          //柱状图
          this.initChart2();
        }

      }).finally(() => {
        this.zztLoading = false;
      });

      this.zdbbLoading = true;
      arm(pms).then(res => {
        let arrs = [];
        for (const resKey in res.data) {
          if (resKey == 'armChild') {
            for (const resKeyKey in res.data[resKey]) {
              arrs.push({
                name: resKeyKey,
                value: res.data[resKey][resKeyKey]
              });
            }
            this.screenInfo.armChild = arrs;
          } else {
            this.screenInfo[resKey] = res.data[resKey];
          }
        }
      }).finally(() => {
        this.zdbbLoading = false;
      });

      x86(pms).then(res => {
        let arrs = [];
        for (const resKey in res.data) {
          if (resKey == 'x86Child') {
            for (const resKeyKey in res.data[resKey]) {
              arrs.push({
                name: resKeyKey,
                value: res.data[resKey][resKeyKey]
              });
            }
            this.screenInfo.x86Child = arrs;
          } else {
            this.screenInfo[resKey] = res.data[resKey];
          }
        }
      }).finally(() => {

      });
      czxt(pms).then(res => {
        if (res.data && res.data.os) {
          let arrs = [];
          for (const resKey in res.data.os) {
            arrs.push({
              name: resKey,
              value: res.data.os[resKey]
            });
          }
          this.screenInfo.os = arrs;
        }
      }).finally(() => {

      });


      // this.zdbbLoading = true;
      // let uInfo = this.userDetail;
      // arm({area: uInfo.regionCode, userId: uInfo.userId, ownerUnitCode: uInfo.ownerUnit}).then(res => {
      //   if (res.data) {
      //     //this.screenInfo = res.data;
      //     this.zdbbInfo = res.data;
      //     //this.initChart1();
      //     //this.initChart2();
      //     //this.initChart3();
      //   }
      // }).finally(() => {
      //   this.zdbbLoading = false;
      // });
    },
    initChart1() {
      let xValue = [];
      let yValue = [];

      if (this.screenInfo.sevenDay) {
        this.screenInfo.sevenDay.forEach((item, index) => {
          xValue.push(this.getFormatDay(item.name));
          yValue.push(item.value);
        });
      }


      let d_zxtChart = this.$echarts.init(document.getElementById('d_zxtChart'));
      d_zxtChart.setOption({
        title: {
          show: false,
          text: 'stacked area chart'
        },
        tooltip: {
          show: true,
          trigger: 'axis',
          transitionDuration: 0,
          axisPointer: {
            type: 'cross',
            label: {
              backgroundColor: '#6a7985',
            }
          }
        },
        legend: {
          show: false,
          textStyle: {
            color: '#fff',
            fontSize: '14px'
          }
        },
        grid: {
          left: '2%',
          right: '5%',
          bottom: '6%',
          containLabel: true
        },
        xAxis: {
          type: 'category',
          boundaryGap: false,
          data: xValue,
          axisTick: {
            show: true,
            alignWithLabel: true,
          },
          axisLine: {
            lineStyle: {
              color: '#c7c7c7',
            }
          },
          splitLine: {
            show: false,
            lineStyle: {
              color: '#0f5681',
              tyle: 'dotted'
            }
          },
          axisLabel: {
            show: true,
            textStyle: {
              color: '#333333',
              fontSize: '14px',
            }
          },
        },
        yAxis: {
          type: 'value',
          name: '数量',
          nameTextStyle: {
            color: '#333333',
            fontSize: '14px',
            align: 'right'
          },
          axisLine: {
            show: false,
            lineStyle: {
              color: '#c7c7c7',
            }
          },
          axisTick: {
            show: true,
            alignWithLabel: true,
          },
          splitLine: {
            show: true,
            lineStyle: {
              color: '#e7e7e7',
              tyle: 'dashed'
            }
          },
          axisLabel: {
            show: true,
            align: 'right',
            textStyle: {
              color: '#333333',
              fontSize: '14px',
            }
          },
        },
        series: [
          {
            name: '数量：',
            type: 'line',
            smooth: 'circle',
            smoothSize: '14px',
            itemStyle: {
              borderColor: '#01ecf2',
              color: '#01ECF2'
            },
            emphasis: {
              itemStyle: {
                color: '#01ECF2',
                borderColor: '#b08010',
              },
            },
            areaStyle: {
              color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
                {offset: 0, color: 'rgba(214, 245, 246, 1)'},
                {offset: 0.5, color: 'rgba(214, 245, 246, 0.5)'},
                {offset: 1, color: 'rgba(214, 245, 246, 0)'},
              ])
            },
            lineStyle: {
              color: '#01ecf2',
            },
            data: yValue,
          }
        ]
      })
    },
    initChart3() {
      // 信创设备数量
      let value1 = 0;
      // 非信创设备数量
      let value2 = 0;

      if (this.screenInfo.deviceNum > 0) {
        value1 = this.screenInfo.deviceNum;
      }
      if (this.screenInfo.deviceAll > 0 && this.screenInfo.deviceNum > 0) {
        value2 = this.screenInfo.deviceAll - this.screenInfo.deviceNum;
      }

      let d_yChart = this.$echarts.init(document.getElementById('d_yChart'));
      d_yChart.setOption({
        series: [{
          name: '内圆',
          type: 'pie',
          radius: ['30%'],
          avoidLabelOverlap: false,
          hoverAnimation: false,
          labelLine: {
            normal: {
              show: false,
            }
          },
          data: [{
            value: 100,
            label: {
              normal: {
                show: false,
              }
            },
          }],
          itemStyle: {
            color: function (colors) {
              let colorList = ['#f5f5f5'];
              return colorList[colors.dataIndex];
            },
          }
        }, {
          name: '外圆',
          type: 'pie',
          radius: ['40%', '50%'],
          avoidLabelOverlap: false,
          hoverAnimation: false,
          labelLine: {
            normal: {
              show: true,
            }
          },
          data: [{
            value: value1,
            name: '信创设备',
            label: {
              show: true,
              position: 'outside'
            },
          }, {
            value: value2,
            name: '非信创设备',
            label: {
              show: true,
              position: 'outside'
            },
          }],
          itemStyle: {
            color: function (colors) {
              let colorList = ['#038DFD', '#3DCBC7'];
              return colorList[colors.dataIndex];
            },
          },
        }],
      });
    },
    initChart2() {
      let xValue = [];
      let yValue = [];

      if (this.screenInfo.dept) {
        this.screenInfo.dept.forEach((item, index) => {
          if (this.userDetail.regionCode.length == 4) {
            //市公司 会显示单位和部门按钮
            if (item.type == this.selectBtnType) {
              xValue.push(item.name);
              yValue.push(item.value);
            }
          } else {
            xValue.push(item.name);
            yValue.push(item.value);
          }
        });
      }

      let d_dwChart = this.$echarts.init(document.getElementById('d_dwChart'));
      d_dwChart.setOption({
        dataZoom: [{
          type: 'slider',
          startValue: this.screenInfo.dept && this.screenInfo.dept.length > 6 ? this.screenInfo.dept.length - 6 : 0,
          endValue: this.screenInfo.dept && this.screenInfo.dept.length > 1 ? this.screenInfo.dept.length - 1 : 0,
          show: xValue.length > 0 ? true : false,
          xAxisIndex: [0],
          handleSize: 0,
          height: 12,
          left: '5%',
          right: '5%',
          bottom: 12,
          borderColor: '#8BB6FB',
          fillerColor: '#327EF7',
          backgroundColor: '#eee',
          showDataShadow: false,
          showDetail: false,
          realtime: true,
          filterMode: 'filter',
          handleStyle: {
            borderRadius: '20'
          }
        }],
        tooltip: {
          formatter: function (params) {
            return params.name;
          }
        },
        xAxis: {
          type: 'category',
          data: xValue,
          nameTextStyle: {
            color: '#333333',
            fontSize: '12px',
            align: 'right'
          },
          axisLine: {
            show: false,
            lineStyle: {
              color: '#333333',
            }
          },
          axisLabel: {
            interval: 0,
            rotate: 0,
            maigin: 2,

            formatter: function (params) {
              let newParamsName = '';
              params = params.length <= 6 ? params : params.substring(0, 4) + '...';
              let paramsNameNumber = params.length;
              let provideNumber = 7;
              let rowNumber = Math.ceil(paramsNameNumber / provideNumber);
              if (paramsNameNumber > provideNumber) {
                for (let p = 0; p < rowNumber; p++) {
                  let tempStr = '';
                  let start = p * provideNumber;
                  let end = start + provideNumber;
                  if (p == rowNumber - 1) {
                    tempStr = params.substring(start, paramsNameNumber)
                  } else {
                    tempStr = params.substring(start, end) + '\n';
                  }

                  newParamsName += tempStr;
                }
              } else {
                newParamsName = params;
              }
              return newParamsName;
            },
          },
        },
        yAxis: {
          name: !this.isNoData(this.screenInfo.dept) ? '设备数量' : '',
          type: 'value',
          nameTextStyle: {
            color: '#333333',
            fontSize: '14px',
            align: 'right'
          },
          axisLine: {
            show: false,
            lineStyle: {
              color: '#333333',
            }
          },
        },
        series: [{
          data: yValue,
          type: 'bar',
          barWidth: '30%',
          itemStyle: {
            normal: {
              color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
                {offset: 0, color: 'rgba(36, 117, 247, 1)'},
                {offset: 0.5, color: 'rgba(36, 117, 247, 0.9)'},
                {offset: 1, color: 'rgba(36, 117, 247, 0.5)'},
              ])
            }
          },
          label: {
            show: true,
            position: 'top',
            textStyle: {
              color: '#1F7CDC',
              fontSize: '14px',
            },
          }
        }],
      });
    },
    typeClick(type) {
      this.selectBtnType = type;
      this.initChart2();
    },
    getFormatDay(value) {
      if (value) {
        let arrs = value.split('-');
        if (arrs && arrs.length == 3) {
          return `${arrs[1]} - ${arrs[2]}`;
        } else {
          return value
        }
      }
      return '';
    },
    getnum(hasnum, allnum) {
      let num = ((hasnum / allnum) * 100).toString()
      var aNew;
      var re = /([0-9]+\.[0-9]{2})[0-9]*/;
      aNew = num.replace(re, "$1");
      return Number(aNew);
    },
    getProgressValue(num) {
      if (isNaN(num)) {
        return 0;
      }

      let ns = JSON.stringify(num);
      let nsArr = ns.split('.');
      if (nsArr && nsArr.length == 2) {
        let length = 0;
        for (let i = 0; i < nsArr[1].length; i++) {
          let c = nsArr[1][i];
          if (c > 0) {
            length = i + 2;
            break;
          }
        }
        ns = num.toFixed(length);
        ns = Number(Number(ns * 100).toFixed(length));
      }
      return ns;
    },
    getRegionCode(length) {
      if (this.userDetail && this.userDetail.regionCode && this.userDetail.regionCode.length == length) {
        return true
      }
      return false;
    },
    isNoData(list) {
      if (list && list.length == 0) {
        return true;
      }
      return false;
    },
  },
}
